<script setup>
import {ref,computed,watch,nextTick,onMounted,onUnmounted} from 'vue'
import {useArcade,shuffle} from '../stores/arcade'
const arcade=useArcade(),game=ref(null),chosen=ref(1),board=ref(null),columns=ref(4),cardWidth=ref(100),gap=ref(8)
let timer,observer,frame
const levels=[{id:1,pairs:4,delay:1200,name:'첫 번째 모험'},{id:2,pairs:6,delay:850,name:'기억력 챌린지'},{id:3,pairs:9,delay:550,name:'마스터의 도전'},{id:4,pairs:12,delay:450,name:'기억의 달인'},{id:5,pairs:15,delay:350,name:'전설의 마스터'}]
const faces=[{id:'eevee',name:'이브이'},{id:'jolteon',name:'쥬피썬더'},{id:'vaporeon',name:'샤미드'},{id:'flareon',name:'부스터'},{id:'glaceon',name:'글레이시아'},{id:'sylveon',name:'님피아'},{id:'leafeon',name:'리피아'},{id:'espeon',name:'에브이'},{id:'umbreon',name:'블래키'}]
const config=computed(()=>levels[chosen.value-1]),gridStyle=computed(()=>({'--columns':columns.value,'--card-width':cardWidth.value+'px','--card-gap':gap.value+'px'}))
function fit(){if(!board.value||!game.value)return;const w=Math.max(1,board.value.clientWidth-20),h=Math.max(1,board.value.clientHeight-20),n=game.value.cards.length;gap.value=w<550?6:10;let best=0,bestColumns=4;for(let cols=1;cols<=Math.min(n,12);cols++){const rows=Math.ceil(n/cols),width=Math.min((w-gap.value*(cols-1))/cols,(h-gap.value*(rows-1))/rows*.75,205);if(width>best){best=width;bestColumns=cols}}columns.value=bestColumns;cardWidth.value=Math.max(10,Math.floor(best))}
async function connectBoard(){await nextTick();observer?.disconnect();if(board.value){observer=new ResizeObserver(()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(fit)});observer.observe(board.value);fit()}}
function start(level=chosen.value){clearTimeout(timer);chosen.value=Number(level);const c=config.value,order=shuffle(faces.map((_,i)=>i)),pairs=Array.from({length:c.pairs},(_,i)=>order[i%order.length]);game.value={cards:shuffle(pairs.flatMap(i=>[i,i])),open:[],matched:[],tries:0,done:false};connectBoard()}
function visible(i){return game.value.open.includes(i)||game.value.matched.includes(i)}
function flip(i){const g=game.value;if(!g||g.done||g.open.length===2||visible(i))return;g.open.push(i);if(g.open.length===2){g.tries++;const[a,b]=g.open;if(g.cards[a]===g.cards[b]){g.matched.push(a,b);g.open=[];if(g.matched.length===g.cards.length)g.done=true}else timer=setTimeout(()=>{if(game.value===g)g.open=[]},config.value.delay)}}
function intro(){clearTimeout(timer);observer?.disconnect();game.value=null}
onMounted(()=>{document.documentElement.classList.add('card-focus-mode');arcade.data.card=null})
onUnmounted(()=>{clearTimeout(timer);cancelAnimationFrame(frame);observer?.disconnect();document.documentElement.classList.remove('card-focus-mode')})
</script>
<template><section class="card-screen"><div v-if="!game" class="card-game-intro"><div class="card-intro-fan" aria-hidden="true"><div class="fan-card fan-back fan-left"><img src="/images/cards/back.png" alt=""/></div><div class="fan-card fan-front"><img src="/images/cards/eevee.png" alt=""/></div><div class="fan-card fan-back fan-right"><img src="/images/cards/back.png" alt=""/></div></div><h1>포켓몬 카드 뒤집기</h1><p>같은 포켓몬 두 장을 찾아요. 레벨을 선택하고 시작하세요.</p><div class="card-intro-levels" aria-label="게임 레벨 선택"><button v-for="level in levels" :key="level.id" :class="['card-level-chip',{selected:chosen===level.id}]" :aria-pressed="chosen===level.id" @click="chosen=level.id"><b>LEVEL {{level.id}}</b><span class="card-level-name">{{level.name}}</span><small>{{level.pairs*2}}장</small></button></div><button class="card-start" @click="start()">START</button><small class="card-reset-note">다른 화면으로 이동하면 이번 게임은 초기화됩니다.</small></div><template v-else><div class="card-play-top"><div class="card-play-title"><h1>카드 뒤집기</h1><select v-model.number="chosen" aria-label="게임 레벨" @change="start(chosen)"><option v-for="level in levels" :key="level.id" :value="level.id">LEVEL {{level.id}} · {{level.pairs*2}}장</option></select></div><div class="card-play-stats"><span>시도 <b>{{game.tries}}</b></span><span>찾은 짝 <b>{{game.matched.length/2}} / {{config.pairs}}</b></span></div><div class="card-play-actions"><button @click="start()">↻ 재시작</button><button class="light" @click="intro">시작 화면</button></div></div><div ref="board" class="card-board-area"><div class="viewport-card-grid" :style="gridStyle"><button v-for="(face,i) in game.cards" :key="i" :class="['memory-card','tcg-card',{revealed:visible(i),matched:game.matched.includes(i)}]" :aria-label="visible(i)?(i+1)+'번 '+faces[face].name+' 카드':(i+1)+'번 카드 뒤집기'" :aria-pressed="visible(i)" :disabled="game.done||game.matched.includes(i)||game.open.includes(i)||game.open.length===2" @click="flip(i)"><span class="tcg-inner"><span class="tcg-side tcg-back"><img src="/images/cards/back.png" alt="" draggable="false"/></span><span class="tcg-side tcg-front"><img :src="'/images/cards/'+faces[face].id+'.png'" alt="" draggable="false"/></span></span><span v-if="game.matched.includes(i)" class="match-check" aria-hidden="true">✓</span></button></div><div v-if="game.done" class="card-clear-overlay"><div class="card-clear-box" role="status"><p class="eyebrow">LEVEL CLEAR!</p><h2>{{chosen===5?'카드 마스터 달성! 🏆':'모든 짝을 찾았어요! 🎉'}}</h2><p>{{game.tries}}번 만에 {{config.pairs}}쌍 완성</p><div class="toolbar"><button v-if="chosen<5" @click="start(chosen+1)">다음 레벨 →</button><button @click="start()">다시 플레이</button><button class="light" @click="intro">시작 화면</button></div></div></div></div><div class="card-play-foot"><span>카드 {{game.cards.length}}장 · 틀린 카드 {{config.delay/1000}}초 공개</span><span>자유 연습 · 포인트 지급 없음</span></div></template></section></template>
